BEGIN;

-- --- devise : 3 lignes ----------------------------------
ON CONFLICT (code_devise) DO UPDATE SET
  libelle = excluded.libelle,
  symbole = excluded.symbole,
  est_pivot = excluded.est_pivot,
  actif = excluded.actif;

-- --- taux_change : 4 lignes -----------------------------
-- Videe d'abord : les seeds la peuplent avec d'autres cles
