-- --- mise en service des qualites --------------------------
-- Le declencheur verifie ICI que chaque qualite a bien une
-- composition. C'est le seul moment ou la verification a un sens.
UPDATE qualite SET statut = 'ACTIF' WHERE code_qualite IN ('8F', '8M', '8S', 'BR', 'FB', 'IS', 'LH', 'LP', 'MF', 'MN', 'MP', 'PS', 'SH', 'SL', 'TN', 'YF', 'YH', 'YL');

COMMIT;
